const contact = $input.first().json.contacts?.[0];

if (!contact) {
  return [{ json: { found: false, is_existing_client: false } }];
}

const customFields = contact.customFields || [];

function getField(fieldId) {
  const field = customFields.find(f => f.id === fieldId);
  return field ? (field.value !== undefined ? field.value : field.fieldValue) : null;
}

const FIELD_IDS = {
  service_address: "YOUR_GHL_FIELD_ID_SERVICE_ADDRESS",
  last_service_date: "YOUR_GHL_FIELD_ID_LAST_SERVICE_DATE",
  stage: "YOUR_GHL_FIELD_ID_STAGE",
  lead_status: "YOUR_GHL_FIELD_ID_LEAD_STATUS"
};

// Existing client = a customer (stage booked or served). Same list as the existing_client_stages row in the
// desertcomfort_config table, kept inline so this in-call lookup makes no extra table read.
// A blank stage (a contact from before the stage field existed) falls back to the old lead status.
// Any other or unknown stage value counts as NOT an existing client (the safe side: the agent just asks again).
const EXISTING_CLIENT_STAGES = ['booked', 'served'];
const LEGACY_BOOKED_STATUSES = ['booked_emergency', 'booked_standard'];
const stage = String(getField(FIELD_IDS.stage) || '').trim().toLowerCase();
const leadStatus = String(getField(FIELD_IDS.lead_status) || '').trim().toLowerCase();
const isExistingClient = stage ? EXISTING_CLIENT_STAGES.includes(stage) : LEGACY_BOOKED_STATUSES.includes(leadStatus);

const TECH_NAMES = {
  YOUR_GHL_USER_ID_4: 'Mario',
  YOUR_GHL_USER_ID_2: 'Brian'
};

const assignedTo = contact.assignedTo || null;

return [{
  json: {
    found: true,
    contact_id: contact.id,
    first_name: contact.firstName || '',
    last_name: contact.lastName || '',
    phone: contact.phone || '',
    service_address: getField(FIELD_IDS.service_address) || '',
    last_service_date: getField(FIELD_IDS.last_service_date) || '',
    assigned_to: assignedTo,
    last_technician: assignedTo ? (TECH_NAMES[assignedTo] || '') : '',
    stage,
    is_existing_client: isExistingClient
  }
}];

// Compute Hours Mode - Part 2 of the business-hours plan (2026-10-06). Reads desertcomfort_config settings rows and
// decides day/night for Phoenix local time. Must never fail open: if the table read errored or came back empty, falls
// back to the hardcoded defaults (08:00-19:00, Mon-Fri, America/Phoenix) so a broken settings read still computes a real answer.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.key);
const cfg = {};
for (const r of rows) cfg[String(r.key).trim()] = r.value;

const DEFAULTS = { business_open_time: '08:00', business_close_time: '19:00', business_open_days: 'Mon,Tue,Wed,Thu,Fri', business_closed_dates: '' };
const usedDefaults = rows.length === 0;
const openTime = String(cfg.business_open_time || DEFAULTS.business_open_time).trim();
const closeTime = String(cfg.business_close_time || DEFAULTS.business_close_time).trim();
const openDays = String(cfg.business_open_days || DEFAULTS.business_open_days).split(',').map((s) => s.trim()).filter(Boolean);
const closedDates = String(cfg.business_closed_dates || DEFAULTS.business_closed_dates).split(',').map((s) => s.trim()).filter(Boolean);

const now = DateTime.now().setZone('America/Phoenix');
const dateStr = now.toFormat('yyyy-MM-dd');
const dayName = now.toFormat('ccc');
const hm = now.toFormat('HH:mm');

let mode = 'day';
let reason = '';
if (closedDates.includes(dateStr)) { mode = 'night'; reason = `closed date ${dateStr}`; }
else if (!openDays.includes(dayName)) { mode = 'night'; reason = `${dayName} is not an open day`; }
else if (hm < openTime) { mode = 'night'; reason = `${hm} Phoenix is before opening (${openTime})`; }
else if (hm >= closeTime) { mode = 'night'; reason = `${hm} Phoenix is at/after closing (${closeTime})`; }
else { reason = `${hm} Phoenix on ${dayName} is within ${openTime}-${closeTime}`; }

if (usedDefaults) reason += ' [config table read failed or empty, used built-in defaults]';

return [{ json: { hours_mode: mode, hours_reason: reason } }];

