  if (data && typeof data === "object" && !Array.isArray(data)) {
    text = buildSoonestText(data, night);
  }
} catch (e) {
  text = "";
}

return [{ json: { text } }];

const ORDINAL = (n) => {
  const s = ["th", "st", "nd", "rd"];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
};

const NUMBER_WORDS = {
  0: "zero", 1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
  6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
  11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen", 15: "fifteen",
  16: "sixteen", 17: "seventeen", 18: "eighteen", 19: "nineteen",
  20: "twenty", 30: "thirty", 40: "forty", 50: "fifty"
};

function minuteWord(min) {
  if (min < 10) return `oh-${NUMBER_WORDS[min]}`;
  if (NUMBER_WORDS[min]) return NUMBER_WORDS[min];
  const tens = Math.floor(min / 10) * 10;
  const ones = min % 10;
  return `${NUMBER_WORDS[tens]}-${NUMBER_WORDS[ones]}`;
}

function speakTime(isoString) {
  const d = new Date(isoString);
  if (isNaN(d.getTime())) return null;
  const opts = { timeZone: "America/Phoenix", hour: "numeric", minute: "numeric", hour12: true };
  const parts = new Intl.DateTimeFormat("en-US", opts).formatToParts(d);
  const hourNum = parseInt(parts.find(p => p.type === "hour").value, 10);
  const minute = parseInt(parts.find(p => p.type === "minute").value, 10);
  const dayPeriod = parts.find(p => p.type === "dayPeriod").value.toLowerCase();
  const hourWord = NUMBER_WORDS[hourNum] || String(hourNum);

  if (minute === 0) return `${hourWord} ${dayPeriod}`;
  return `${hourWord}-${minuteWord(minute)} ${dayPeriod}`;
}

function speakDateLabel(dateKey, todayKey, tomorrowKey) {
  const d = new Date(dateKey + "T12:00:00-07:00");
  if (isNaN(d.getTime())) return null;
  const weekday = new Intl.DateTimeFormat("en-US", { timeZone: "America/Phoenix", weekday: "long" }).format(d);
  const month = new Intl.DateTimeFormat("en-US", { timeZone: "America/Phoenix", month: "long" }).format(d);
  const dayNum = parseInt(new Intl.DateTimeFormat("en-US", { timeZone: "America/Phoenix", day: "numeric" }).format(d), 10);
  const dateLabel = `${weekday} ${month} ${ORDINAL(dayNum)}`;

  if (dateKey === todayKey) return `Today being ${dateLabel}`;
  if (dateKey === tomorrowKey) return `Tomorrow being ${dateLabel}`;
  return dateLabel;
}

function joinTimes(times) {
  if (times.length === 1) return `only availability is at ${times[0]}`;
  if (times.length === 2) return `at ${times[0]} and ${times[1]}`;
  return `at ${times.slice(0, -1).join(", ")}, and ${times[times.length - 1]}`;
}

function buildAvailabilityText(data) {
  const DATE_KEY_RE = /^\d{4}-\d{2}-\d{2}$/;

  const nowMST = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Phoenix" }));
  const todayKey = nowMST.toISOString().slice(0, 10);
  const tomorrow = new Date(nowMST);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowKey = tomorrow.toISOString().slice(0, 10);

  const sortedDateKeys = Object.keys(data).filter(k => DATE_KEY_RE.test(k)).sort();

  const lines = [];
  for (const dateKey of sortedDateKeys) {
    const rawSlots = data[dateKey]?.slots;
    if (!Array.isArray(rawSlots) || rawSlots.length === 0) continue;

    const dateLabel = speakDateLabel(dateKey, todayKey, tomorrowKey);
    if (dateLabel === null) continue;

    const uniqueSorted = [...new Set(rawSlots)].sort();
    const spokenTimes = uniqueSorted
      .map(speakTime)
      .filter(t => t !== null);
    if (spokenTimes.length === 0) continue;

    lines.push(`${dateLabel}: ${joinTimes(spokenTimes)}.`);
  }

  return lines.join("  \n");
}

let text = "";
try {
  const data = $input.first().json;
  if (data && typeof data === "object" && !Array.isArray(data)) {
    text = buildAvailabilityText(data);
  }
} catch (e) {
  text = "";
}

return [{ json: { text } }];

const ORDINAL_WORDS = {
  1: "first", 2: "second", 3: "third", 4: "fourth", 5: "fifth",
  6: "sixth", 7: "seventh", 8: "eighth", 9: "ninth", 10: "tenth",
  11: "eleventh", 12: "twelfth", 13: "thirteenth", 14: "fourteenth", 15: "fifteenth",
  16: "sixteenth", 17: "seventeenth", 18: "eighteenth", 19: "nineteenth", 20: "twentieth",
  21: "twenty-first", 22: "twenty-second", 23: "twenty-third", 24: "twenty-fourth", 25: "twenty-fifth",
  26: "twenty-sixth", 27: "twenty-seventh", 28: "twenty-eighth", 29: "twenty-ninth", 30: "thirtieth",
  31: "thirty-first",
};
const ORDINAL = (n) => ORDINAL_WORDS[n] || String(n);

const NUMBER_WORDS = {
  0: "zero", 1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
  6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
  11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen", 15: "fifteen",
  16: "sixteen", 17: "seventeen", 18: "eighteen", 19: "nineteen",
  20: "twenty", 30: "thirty", 40: "forty", 50: "fifty"
};

function minuteWord(min) {
  if (min < 10) return `oh-${NUMBER_WORDS[min]}`;
  if (NUMBER_WORDS[min]) return NUMBER_WORDS[min];
  const tens = Math.floor(min / 10) * 10;
  const ones = min % 10;
  return `${NUMBER_WORDS[tens]}-${NUMBER_WORDS[ones]}`;
}

function speakTime(isoString) {
  const d = new Date(isoString);
  if (isNaN(d.getTime())) return null;
  const opts = { timeZone: "America/Phoenix", hour: "numeric", minute: "numeric", hour12: true };
  const parts = new Intl.DateTimeFormat("en-US", opts).formatToParts(d);
  const hourNum = parseInt(parts.find(p => p.type === "hour").value, 10);
  const minute = parseInt(parts.find(p => p.type === "minute").value, 10);
  const dayPeriod = parts.find(p => p.type === "dayPeriod").value.toLowerCase();
  const hourWord = NUMBER_WORDS[hourNum] || String(hourNum);

  if (minute === 0) return `${hourWord} ${dayPeriod}`;
  return `${hourWord}-${minuteWord(minute)} ${dayPeriod}`;
}

function speakOrdinalDateLabel(dateKey, todayKey, tomorrowKey) {
  const d = new Date(dateKey + "T12:00:00-07:00");
  if (isNaN(d.getTime())) return null;
  const weekday = new Intl.DateTimeFormat("en-US", { timeZone: "America/Phoenix", weekday: "long" }).format(d);
  const dayNum = parseInt(new Intl.DateTimeFormat("en-US", { timeZone: "America/Phoenix", day: "numeric" }).format(d), 10);
  const dateLabel = `${weekday} the ${ORDINAL(dayNum)}`;

  if (dateKey === todayKey) return { prefix: "today being", dateLabel };
  if (dateKey === tomorrowKey) return { prefix: "tomorrow being", dateLabel };
  return { prefix: null, dateLabel };
}

function buildSoonestText(data, night) {
  const DATE_KEY_RE = /^\d{4}-\d{2}-\d{2}$/;

  const nowMST = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Phoenix" }));
  const todayKey = nowMST.toISOString().slice(0, 10);
  const tomorrow = new Date(nowMST);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowKey = tomorrow.toISOString().slice(0, 10);

  const sortedDateKeys = Object.keys(data).filter(k => DATE_KEY_RE.test(k)).sort();

  const allSlots = [];
  for (const dateKey of sortedDateKeys) {
    const rawSlots = data[dateKey]?.slots;
    if (!Array.isArray(rawSlots)) continue;
    const uniqueSorted = [...new Set(rawSlots)].sort();
    for (const iso of uniqueSorted) {
      allSlots.push({ dateKey, iso });
    }
  }

  // After-hours calls: ONE finished sentence with only the first open time, no choice. The tool says it; the prompt only speaks it.
  if (night) {
    const first = allSlots[0];
    if (!first) return "";
    const label = speakOrdinalDateLabel(first.dateKey, todayKey, tomorrowKey);
    const time = speakTime(first.iso);
    if (label === null || time === null) return "";
    const when = label.prefix ? `${label.prefix.replace(" being", "")}, ${label.dateLabel},` : label.dateLabel;
    return `The soonest I can get a technician out is ${when} at ${time}, and I'll book it for you right now - does that work?`;
  }

  const picked = allSlots.slice(0, 2);
  if (picked.length === 0) return "";

  const byDate = [];
  for (const slot of picked) {
    let group = byDate.find((g) => g.dateKey === slot.dateKey);
    if (!group) {
      group = { dateKey: slot.dateKey, times: [] };
      byDate.push(group);
    }
    group.times.push(slot.iso);
  }

  const clauses = [];
  for (const group of byDate) {
    const label = speakOrdinalDateLabel(group.dateKey, todayKey, tomorrowKey);
    if (label === null) continue;
    const spokenTimes = group.times.map(speakTime).filter((t) => t !== null);
    if (spokenTimes.length === 0) continue;

    const prefixPart = label.prefix ? `${label.prefix} ${label.dateLabel}` : label.dateLabel;
    if (spokenTimes.length === 1) {
      clauses.push(`${prefixPart} at ${spokenTimes[0]}`);
    } else {
      clauses.push(`${prefixPart} at ${spokenTimes[0]} Arizona time and also at ${spokenTimes[1]}`);
    }
  }

  if (clauses.length === 0) return "";

  let inner;
  if (clauses.length === 1) {
    inner = clauses[0];
  } else {
    inner = `${clauses[0]} Arizona time and ${clauses[1]}`;
  }
  return `We have availability ${inner}. When works for you?`;
}

// hours_mode comes from the agent's own call-start clock check (code, never the model). Anything but exactly "night" keeps the day answer.
let night = false;
try {
  night = $("Check Availability and Book Desert Comfort LiveKit").first().json.body.hours_mode === "night";
} catch (e) {
  night = false;
}

let text = "";
try {
  const data = $("Get Available Slots GHL Standard").first().json;
  if (data && typeof data === "object" && !Array.isArray(data)) {
    text = buildSoonestText(data, night);
  }
} catch (e) {
  text = "";
}

return [{ json: { text } }];

// Validate Book Appointment Parameters (Step 4 caller-facing containment)
// Structural validation only — not a semantic/intent check.

const errors = [];

function isSaneName(value, fieldName, required) {
  if (!value || typeof value !== 'string' || value.trim().length === 0) {
    if (required) errors.push({ field: fieldName, reason: 'missing or empty' });
    return;
  }
  const trimmed = value.trim();
  if (/^(null|undefined|n\/a|none)$/i.test(trimmed)) {
    if (required) errors.push({ field: fieldName, reason: 'literal "null"/"n/a" string, not a real value' });
    return;
  }
  if (trimmed.length > 50) {
    errors.push({ field: fieldName, reason: 'exceeds 50 characters — not a plausible name' });
  }
  if (/\d/.test(trimmed)) {
    errors.push({ field: fieldName, reason: 'contains digits — not a plausible name' });
  }
  const wordCount = trimmed.split(/\s+/).length;
  if (wordCount > 4 || /[.!?]$/.test(trimmed)) {
    errors.push({ field: fieldName, reason: 'sentence-shaped value, not a plausible name' });
  }
}

const booking = $('Set Book Parameters').first().json;

isSaneName(booking.first_name, 'first_name', false);
isSaneName(booking.last_name, 'last_name', false);

function isSanePhone(value) {
  if (!value || typeof value !== 'string') {
    errors.push({ field: 'phone_number', reason: 'missing or empty' });
    return;
  }
  const digitsOnly = value.replace(/\D/g, '');
  const validNanp = /^1?\d{10}$/.test(digitsOnly) && digitsOnly.length >= 10 && digitsOnly.length <= 11;
  if (!validNanp) {
    errors.push({ field: 'phone_number', reason: 'does not parse as a valid US/Canada phone number' });
  }
}
isSanePhone(booking.phone_number);

let normalizedPhone = null;
function normalizePhone(value) {
  if (!value || typeof value !== 'string') return null;
  const digitsOnly = value.replace(/\D/g, '');
  if (digitsOnly.length === 10) return '+1' + digitsOnly;
  if (digitsOnly.length === 11 && digitsOnly.startsWith('1')) return '+' + digitsOnly;
  return null;
}
normalizedPhone = normalizePhone(booking.phone_number);

function isSaneAddress(value) {
  if (!value || typeof value !== 'string' || value.trim().length === 0) {
    errors.push({ field: 'address', reason: 'missing or empty' });
    return;
  }
  if (value.trim().length > 200) {
    errors.push({ field: 'address', reason: 'exceeds 200 characters — not a plausible address' });
  }
}
isSaneAddress(booking.address);

let normalizedAbsoluteTime = null;
function isSaneAppointmentTime(value) {
  if (!value || typeof value !== 'string') {
    errors.push({ field: 'absolute_time', reason: 'missing or empty' });
    return;
  }
  const zoned = DateTime.fromISO(value, { zone: 'America/Phoenix' });
  if (!zoned.isValid) {
    errors.push({ field: 'absolute_time', reason: 'not a valid ISO timestamp' });
    return;
  }
  normalizedAbsoluteTime = zoned.toISO({ suppressMilliseconds: true });
  const now = DateTime.now().setZone('America/Phoenix');
  const graceMs = 5 * 60 * 1000;
  if (zoned.toMillis() < now.toMillis() - graceMs) {
    errors.push({ field: 'absolute_time', reason: 'appointment time is in the past' });
  }
  const maxOutMs = 30 * 24 * 60 * 60 * 1000;
  if (zoned.toMillis() > now.toMillis() + maxOutMs) {
    errors.push({ field: 'absolute_time', reason: 'appointment time is more than 30 days out — outside any plausible offered window' });
  }
}
isSaneAppointmentTime(booking.absolute_time);

// Business-hours check (Part 3, 2026-10-06): STANDARD bookings only -- emergency calendar is 24/7, never blocked here.
const cfgRows = ($json.rows) || [];
const cfg = {};
for (const r of cfgRows) { if (r && r.key) cfg[String(r.key).trim()] = r.value; }
const HOURS_DEFAULTS = { business_open_time: '08:00', business_close_time: '19:00', business_open_days: 'Mon,Tue,Wed,Thu,Fri', business_closed_dates: '' };
const openTime = String(cfg.business_open_time || HOURS_DEFAULTS.business_open_time).trim();
const closeTime = String(cfg.business_close_time || HOURS_DEFAULTS.business_close_time).trim();
const openDays = String(cfg.business_open_days || HOURS_DEFAULTS.business_open_days).split(',').map((s) => s.trim()).filter(Boolean);
const closedDates = String(cfg.business_closed_dates || HOURS_DEFAULTS.business_closed_dates).split(',').map((s) => s.trim()).filter(Boolean);
if (booking.urgent !== true && normalizedAbsoluteTime) {
  const apptZoned = DateTime.fromISO(normalizedAbsoluteTime, { zone: 'America/Phoenix' });
  const apptDate = apptZoned.toFormat('yyyy-MM-dd');
  const apptDay = apptZoned.toFormat('ccc');
  const apptHm = apptZoned.toFormat('HH:mm');
  const lastSlotHm = DateTime.fromFormat(closeTime, 'HH:mm').minus({ hours: 1 }).toFormat('HH:mm');
  if (closedDates.includes(apptDate)) {
    errors.push({ field: 'absolute_time', reason: `${apptDate} is a closed date for standard bookings` });
  } else if (!openDays.includes(apptDay)) {
    errors.push({ field: 'absolute_time', reason: `${apptDay} is not an open day for standard bookings` });
  } else if (apptHm < openTime) {
    errors.push({ field: 'absolute_time', reason: `${apptHm} Phoenix is before opening (${openTime}) for standard bookings` });
  } else if (apptHm > lastSlotHm) {
    errors.push({ field: 'absolute_time', reason: `${apptHm} Phoenix is later than the last standard slot (${lastSlotHm}, one hour before closing)` });
  }
}

if (typeof booking.urgent !== 'boolean') {
  errors.push({ field: 'urgent', reason: 'missing or not a boolean' });
}

const valid = errors.length === 0;

return {
  json: {
    ...booking,
    absolute_time_iso: normalizedAbsoluteTime,
    phone_number_e164: normalizedPhone,
    valid,
    errors,
  }
};

