// Validate Opt Out Parameters - never throws. Unrecognized channels defaults to the
// broadest suppression (fail toward suppressing, never toward contacting) - the internal contact-state model section 6.
const src = $input.first().json;
const phone = String(src.phone || '').trim();
const rawChannels = String(src.channels || '').trim();
const channels = rawChannels.toLowerCase() === 'sms_only' ? 'sms_only' : 'call_and_sms';
let invalid = '';
if (!phone) invalid = 'missing caller phone number';
return [{ json: { phone, channels, raw_channels: rawChannels, invalid } }];

// Decide Opt Out DND - pure decision logic, writes nothing itself. Mirrors Decide Telnyx SMS DND's shape.
const req = $('Validate Opt Out Parameters').first().json;
const up = $('Upsert Contact For Opt Out').first().json;
const base = { phone: req.phone, channels: req.channels, contact_id: '', decision: '', reason: '', dnd_body: null };

if (req.invalid) {
  return [{ json: { ...base, decision: 'invalid_input', reason: req.invalid } }];
}
const contact = up.body && up.body.contact;
if (up.statusCode >= 300 || !contact || !contact.id) {
  return [{ json: { ...base, decision: 'upsert_failed', reason: `GHL upsert returned ${up.statusCode}` } }];
}
const dnd_body = req.channels === 'sms_only'
  ? { dndSettings: { SMS: { status: 'active', message: 'ConvertEcho: caller opt-out (voice)', code: 'VOICE_OPT_OUT' } } }
  : { dndSettings: { Call: { status: 'active', message: 'ConvertEcho: caller opt-out (voice)', code: 'VOICE_OPT_OUT' }, SMS: { status: 'active', message: 'ConvertEcho: caller opt-out (voice)', code: 'VOICE_OPT_OUT' } } };
return [{ json: { ...base, contact_id: contact.id, decision: `opted_out_${req.channels}`, reason: 'caller opt-out during live call', dnd_body } }];

