// Validate Grant Opt In Parameters - strict, unlike opt-out. An unrecognized channels
// value is REJECTED, never defaulted to a wider grant than the caller actually confirmed.
const src = $input.first().json;
const phone = String(src.phone || '').trim();
const channels = String(src.channels || '').trim().toLowerCase();
const VALID = new Set(['call_and_sms', 'call_only', 'sms_only']);
let invalid = '';
if (!phone) invalid = 'missing caller phone number';
else if (!VALID.has(channels)) invalid = `channels must be call_and_sms/call_only/sms_only, got "${String(src.channels || '')}"`;
return [{ json: { phone, channels, invalid } }];

// Decide Grant Opt In DND - pure decision logic, writes nothing itself.
// Only clears DND for an EXISTING contact -- nothing to opt back in if none exists, never upsert here.
const req = $('Validate Grant Opt In Parameters').first().json;
const sr = $('Search Contact For Grant Opt In').first().json;
const base = { phone: req.phone, channels: req.channels, contact_id: '', decision: '', reason: '', dnd_body: null };

if (req.invalid) {
  return [{ json: { ...base, decision: 'invalid_input', reason: req.invalid } }];
}
if (sr.statusCode !== 200) {
  return [{ json: { ...base, decision: 'search_failed', reason: `GHL search returned ${sr.statusCode}` } }];
}
const contacts = (sr.body && sr.body.contacts) || [];
if (contacts.length === 0) {
  return [{ json: { ...base, decision: 'contact_not_found', reason: `no GHL contact for ${req.phone} - nothing to opt back in` } }];
}
let contact = contacts[0];
let ambiguous = contacts.length > 1;
if (ambiguous) {
  contact = [...contacts].sort((a, b) => new Date(b.dateUpdated || b.dateAdded || 0) - new Date(a.dateUpdated || a.dateAdded || 0))[0];
}
const CHANNEL_MAP = {
  call_and_sms: { Call: { status: 'inactive' }, SMS: { status: 'inactive' } },
  call_only: { Call: { status: 'inactive' } },
  sms_only: { SMS: { status: 'inactive' } },
};
const dnd_body = { dndSettings: CHANNEL_MAP[req.channels] || CHANNEL_MAP.call_and_sms };
return [{ json: { ...base, contact_id: contact.id, decision: `opted_in_${req.channels}`, reason: ambiguous ? `${contacts.length} contacts matched, picked most recently updated` : 'caller re-opted-in during live call', dnd_body } }];

