// Validate Check Availability Parameters (Step 4 caller-facing containment)
// Guards against the model sending non-boolean values, which would otherwise
// silently misroute (treated as falsy/non-urgent) instead of erroring.

const errors = [];
const body = $json.body || {};

function isSaneBoolean(value, fieldName) {
  if (typeof value !== 'boolean') {
    errors.push({ field: fieldName, reason: `must be a true/false value, got ${JSON.stringify(value)}` });
  }
}
isSaneBoolean(body.urgent, 'urgent');
// last_technician is optional — the real tool schema does not always send it.
// Only validate its type when the caller actually provided it; absent = treated as false downstream.
if (body.last_technician !== undefined) {
  isSaneBoolean(body.last_technician, 'last_technician');
}

const valid = errors.length === 0;

return {
  json: {
    ...$json,
    valid,
    errors,
  }
};

