parameters.jsCode:
// Verify Telnyx Signature - Ed25519 per Telnyx's documented scheme: sign(timestamp + '|' + raw_body),
// headers telnyx-signature-ed25519 (base64) + telnyx-timestamp (unix seconds).
// Public key is NOT a secret -- it's the verification half of the keypair, safe to hardcode.
// Rotate here if Telnyx ever rotates it: Mission Control > Account Settings > Keys & Credentials > Public Key.
const TELNYX_PUBLIC_KEY_B64 = 'YOUR_BASE64_PUBLIC_KEY';
const MAX_SKEW_SECONDS = 300;

const item = $input.first();
const headers = item.json.headers || {};
const sigHeader = headers['telnyx-signature-ed25519'];
const tsHeader = headers['telnyx-timestamp'];
const bin = item.binary && item.binary.data;

const result = { valid: false, reason: '' };

if (!sigHeader || !tsHeader) { result.reason = 'missing signature or timestamp header'; return [{ json: result }]; }
if (!bin) { result.reason = 'no raw body captured (rawBody option off?)'; return [{ json: result }]; }

const rawBody = Buffer.from(bin.data, 'base64').toString('utf8');

const skew = Math.abs(Date.now() / 1000 - Number(tsHeader));
if (!Number.isFinite(skew) || skew > MAX_SKEW_SECONDS) { result.reason = `timestamp skew ${skew}s exceeds ${MAX_SKEW_SECONDS}s`; return [{ json: result }]; }

try {
  const crypto = require('crypto');
  const ED25519_SPKI_PREFIX = Buffer.from('302a300506032b6570032100', 'hex');
  const rawPub = Buffer.from(TELNYX_PUBLIC_KEY_B64, 'base64');
  const publicKey = crypto.createPublicKey({ key: Buffer.concat([ED25519_SPKI_PREFIX, rawPub]), format: 'der', type: 'spki' });
  const signedData = Buffer.from(`${tsHeader}|${rawBody}`, 'utf8');
  const signature = Buffer.from(sigHeader, 'base64');
  result.valid = crypto.verify(null, signedData, publicKey, signature);
  if (!result.valid) result.reason = 'signature mismatch';
} catch (e) {
  result.reason = `verification error: ${e.message}`;
}
return [{ json: result }];

