parameters.jsCode:
// Parse Telnyx SMS Event - recognizes STOP/START keywords on a verified message.received event.
// Keyword list matches the standard carrier-recognized SMS opt-out/in words (same ones Telnyx's own
// carrier-level auto-handling reacts to), so our mirror stays in sync with what Telnyx already enforces.
const body = ($('Receive Telnyx Inbound SMS Desert Comfort LiveKit').first().json.body) || {};
const data = body.data || {};
const payload = data.payload || {};
const eventType = data.event_type || '';
const direction = String(payload.direction || '').toLowerCase();
const text = String(payload.text || '').trim();
const fromNumber = (payload.from && payload.from.phone_number) || '';
const toNumbers = (payload.to || []).map((t) => t && t.phone_number).filter(Boolean);
const OUR_NUMBER = 'YOUR_BUSINESS_PHONE_NUMBER';

const STOP_WORDS = ['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit'];
const START_WORDS = ['start', 'yes', 'unstop'];
const normalized = text.toLowerCase().replace(/[^a-z]/g, '');

let kind = '';
if (STOP_WORDS.includes(normalized)) kind = 'stop';
else if (START_WORDS.includes(normalized)) kind = 'start';

const recognized = eventType === 'message.received' && direction === 'inbound' && toNumbers.includes(OUR_NUMBER) && kind !== '';

return [{ json: { recognized, kind, from_number: fromNumber, text, event_type: eventType, direction, to_numbers: toNumbers } }];

// Decide Telnyx SMS DND - pure decision logic, writes nothing itself.
// Never silently picks contacts[0] on ambiguity -- sorts by most recently updated and alerts so a human
// double-checks. No contact found means no write, alert instead of guessing.
const ev = $('Parse Telnyx SMS Event Desert Comfort LiveKit').first().json;
const sr = $('Search Contact For Telnyx SMS Desert Comfort LiveKit').first().json;
const contacts = (sr.statusCode === 200 && sr.body && sr.body.contacts) || [];

const base = { kind: ev.kind, from_number: ev.from_number, contact_id: '', decision: '', reason: '', alert: false, alert_text: '', dnd_body: null };

if (sr.statusCode !== 200) {
  return [{ json: { ...base, decision: 'search_failed', reason: `GHL search returned ${sr.statusCode}`, alert: true,
    alert_text: `Telnyx inbound SMS "${ev.kind.toUpperCase()}" from ${ev.from_number}: GHL contact search failed (HTTP ${sr.statusCode}). DND NOT mirrored.` } }];
}
if (contacts.length === 0) {
  return [{ json: { ...base, decision: 'contact_not_found', reason: `no GHL contact for ${ev.from_number}`, alert: true,
    alert_text: `Telnyx inbound SMS "${ev.kind.toUpperCase()}" from ${ev.from_number}, but no matching GHL contact was found. DND NOT mirrored.` } }];
}
let contact = contacts[0];
let ambiguous = false;
if (contacts.length > 1) {
  ambiguous = true;
  contact = [...contacts].sort((a, b) => new Date(b.dateUpdated || b.dateAdded || 0) - new Date(a.dateUpdated || a.dateAdded || 0))[0];
}
const contact_id = contact.id;

const dnd_body = ev.kind === 'stop'
  ? { dndSettings: { Call: { status: 'active', message: 'ConvertEcho: SMS STOP reply', code: 'TELNYX_SMS_STOP' }, SMS: { status: 'active', message: 'ConvertEcho: SMS STOP reply', code: 'TELNYX_SMS_STOP' } } }
  : { dndSettings: { SMS: { status: 'inactive' } } };

return [{ json: { ...base, contact_id, decision: `mirrored_${ev.kind}`, reason: `${ev.kind.toUpperCase()} reply mirrored to GHL DND`, dnd_body,
  alert: ambiguous, alert_text: ambiguous ? `Telnyx SMS ${ev.kind.toUpperCase()} from ${ev.from_number} matched ${contacts.length} GHL contacts; picked most recently updated (${contact_id}). Verify this was correct.` : '' } }];

